const listRecommendedPriceVersions = `-- name: ListRecommendedPriceVersions :many
SELECT v.id, v.uuid, v.organization_id, v.brand_id, v.product_id, v.country_id, v.currency, v.price, v.effective_from, v.source, v.published_by_user_id, v.published_at, v.batch_id, v.note, v.superseded_at,
       p.name AS product_name,
       p.sku AS product_sku,
       p.uuid AS product_uuid,
       COALESCE(co.iso2, '')::text AS country_iso2,
       COALESCE(co.name_en, '')::text AS country_name_en,
       COALESCE(co.name_tr, '')::text AS country_name_tr,
       TRIM(COALESCE(u.name, '') || ' ' || COALESCE(u.surname, ''))::text AS published_by_name,
       (c.id IS NOT NULL)::bool AS is_current,
       COUNT(*) OVER()::bigint AS total_count
FROM recommended_price_versions v
JOIN products p ON p.id = v.product_id
LEFT JOIN countries co ON co.id = v.country_id
LEFT JOIN users u ON u.id = v.published_by_user_id
LEFT JOIN recommended_prices_current c ON c.version_id = v.id
WHERE v.brand_id = $1
  AND (COALESCE(cardinality($2::bigint[]), 0) = 0
       OR v.product_id = ANY ($2::bigint[]))
  AND (COALESCE(cardinality($3::bigint[]), 0) = 0
       OR COALESCE(v.country_id, 0) = ANY ($3::bigint[]))
  AND (COALESCE(cardinality($4::text[]), 0) = 0
       OR v.currency = ANY ($4::text[]))
  AND (COALESCE(cardinality($5::text[]), 0) = 0
       OR v.source = ANY ($5::text[]))
  AND ($6::uuid IS NULL OR v.batch_id = $6::uuid)
  AND ($7::date IS NULL OR v.effective_from >= $7::date)
  AND ($8::date IS NULL OR v.effective_from < $8::date)
  AND ($9::text IS NULL
       OR p.name ILIKE '%' || $9::text || '%'
       OR p.sku ILIKE '%' || $9::text || '%')
ORDER BY
  CASE WHEN NOT $10::bool AND $11::text = 'effective_from' THEN v.effective_from END ASC,
  CASE WHEN $10::bool AND $11::text = 'effective_from' THEN v.effective_from END DESC,
  CASE WHEN NOT $10::bool AND $11::text = 'published_at' THEN v.published_at END ASC,
  CASE WHEN $10::bool AND $11::text = 'published_at' THEN v.published_at END DESC,
  CASE WHEN NOT $10::bool AND $11::text = 'price' THEN v.price END ASC,
  CASE WHEN $10::bool AND $11::text = 'price' THEN v.price END DESC,
  CASE WHEN $10::bool THEN v.id END DESC,
  v.id ASC
LIMIT $13 OFFSET $12
`

