const withdrawRecommendedPrice = `-- name: WithdrawRecommendedPrice :execrows
WITH removed AS (
    DELETE FROM recommended_prices_current rc
    WHERE rc.brand_id = $1
      AND rc.product_id = $2
      AND rc.country_id IS NOT DISTINCT FROM $3::bigint
      AND rc.currency = $4
    RETURNING rc.version_id
)
UPDATE recommended_price_versions v
SET superseded_at = GREATEST(NOW(), v.published_at)
FROM removed
WHERE v.id = removed.version_id AND v.superseded_at IS NULL
`

type WithdrawRecommendedPriceParams struct {
	BrandID   int64       `json:"brand_id"`
	ProductID int64       `json:"product_id"`
	CountryID pgtype.Int8 `json:"country_id"`
	Currency  string      `json:"currency"`
}

// Removes a recommendation from the projection and supersedes its version;
// for country NULL product_prices.recommended_sale_price becomes NULL.
func (q *Queries) WithdrawRecommendedPrice(ctx context.Context, arg WithdrawRecommendedPriceParams) (int64, error) {
	result, err := q.db.Exec(ctx, withdrawRecommendedPrice,
		arg.BrandID,
		arg.ProductID,
		arg.CountryID,
		arg.Currency,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
